from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    result = []

    def add_if_valid(year, month, day):
        try:
            candidate = date(year, month, day)
        except ValueError:
            return
        if candidate >= start_date:
            result.append(candidate)

    if kind == "DAILY":
        current = start_date
        step = timedelta(days=interval)
        while len(result) < count:
            result.append(current)
            current += step

    elif kind == "WEEKLY":
        weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                    "FR": 4, "SA": 5, "SU": 6}
        selected = sorted(weekdays[token] for token in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0
        while len(result) < count:
            if week_index % interval == 0:
                for weekday in selected:
                    candidate = week_start + timedelta(
                        weeks=week_index, days=weekday
                    )
                    if candidate >= start_date:
                        result.append(candidate)
                        if len(result) == count:
                            break
            week_index += 1

    elif kind == "MONTHLY":
        if len(parts) == 3:
            day_spec = int(parts[2])
            month_index = 0
            while len(result) < count:
                absolute_month = (start_date.year * 12 + start_date.month - 1
                                  + month_index)
                year, month_zero = divmod(absolute_month, 12)
                month = month_zero + 1
                if month_index % interval == 0:
                    last_day = calendar.monthrange(year, month)[1]
                    day = last_day if day_spec == -1 else day_spec
                    if day <= last_day:
                        add_if_valid(year, month, day)
                month_index += 1
        else:
            weekday_codes = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                             "FR": 4, "SA": 5, "SU": 6}
            occurrence = int(parts[2])
            weekday = weekday_codes[parts[3]]
            month_index = 0
            while len(result) < count:
                absolute_month = (start_date.year * 12 + start_date.month - 1
                                  + month_index)
                year, month_zero = divmod(absolute_month, 12)
                month = month_zero + 1
                if month_index % interval == 0:
                    last_day = calendar.monthrange(year, month)[1]
                    if occurrence == -1:
                        day = last_day - (
                            (date(year, month, last_day).weekday() - weekday) % 7
                        )
                    else:
                        first_weekday = date(year, month, 1).weekday()
                        day = 1 + (weekday - first_weekday) % 7
                        day += 7 * (occurrence - 1)
                    if day <= last_day:
                        add_if_valid(year, month, day)
                month_index += 1

    elif kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year_index = 0
        while len(result) < count:
            year = start_date.year + year_index
            if year_index % interval == 0:
                add_if_valid(year, month, day)
            year_index += 1

    return [d.isoformat() for d in result]
